// Generated by Claude/specs/courses-tools/sync-ielts-exams.js from Claude/specs/lxd-course-ielts-exams/exam-06/ (farin-lxd). Do not hand-edit.
(function(E){ const x = E["exam-06"] = E["exam-06"] || {units:{}}; (x.units = x.units || {})["x06-l1"] = {"id":"x06-l1","patterns":["L1-forms","PARA-time"],"title":{"en":"Listening Part 1: help for a parent","tr":"Listening Part 1: bir ebeveyn için yardım","fa":"Listening Part 1: کمک برای پدر یا مادر"},"objective":{"en":"In this lesson you will learn to complete notes while one neighbour explains a council service to another: catch numbers that sound alike, write a spelled name, and choose the detail that is true now.","tr":"Bu derste bir komşu diğerine bir belediye hizmetini anlatırken notları doldurmayı öğreneceksin: birbirine benzeyen sayıları yakalayacak, harf harf söylenen bir ismi yazacak ve şu anda doğru olan bilgiyi seçeceksin.","fa":"در این درس یاد می‌گیری وقتی یک همسایه خدمتی از شهرداری را برای همسایه‌ی دیگر توضیح می‌دهد، یادداشت‌ها را کامل کنی: عددهای شبیه به هم را تشخیص بدهی، اسمی را که هجی می‌شود بنویسی و اطلاعاتی را که الان درست است انتخاب کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 1: help for a parent","tr":"Listening Part 1: bir ebeveyn için yardım","fa":"Listening Part 1: کمک برای پدر یا مادر"},"objective":{"en":"In this lesson you will learn to complete notes while one neighbour explains a council service to another: catch numbers that sound alike, write a spelled name, and choose the detail that is true now.","tr":"Bu derste bir komşu diğerine bir belediye hizmetini anlatırken notları doldurmayı öğreneceksin: birbirine benzeyen sayıları yakalayacak, harf harf söylenen bir ismi yazacak ve şu anda doğru olan bilgiyi seçeceksin.","fa":"در این درس یاد می‌گیری وقتی یک همسایه خدمتی از شهرداری را برای همسایه‌ی دیگر توضیح می‌دهد، یادداشت‌ها را کامل کنی: عددهای شبیه به هم را تشخیص بدهی، اسمی را که هجی می‌شود بنویسی و اطلاعاتی را که الان درست است انتخاب کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word / number","tr":"1 kelime / sayı","fa":"۱ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: council help for an elderly parent","tr":"Bu sınav: yaşlı bir ebeveyn için belediye yardımı","fa":"این آزمون: کمک شهرداری برای والدِ سالمند"},"intro":{"en":"Part 1 is always an everyday conversation about getting information. Official services, forms and surveys are a regular situation. The notes follow the order of the process, so the speakers’ \"first\", \"then\" and \"what about\" move you down the page.","tr":"Part 1 her zaman bilgi almakla ilgili günlük bir konuşmadır. Resmî hizmetler, formlar ve anketler düzenli çıkan bir durumdur. Notlar sürecin sırasını izler; konuşanların \"first\", \"then\" ve \"what about\" ifadeleri seni sayfada aşağı indirir.","fa":"Part 1 همیشه گفتگویی روزمره برای گرفتن اطلاعات است. خدمات رسمی، فرم‌ها و نظرسنجی‌ها موقعیتی همیشگی‌اند. یادداشت‌ها ترتیب کار را دنبال می‌کنند، پس «first»، «then» و «what about» گوینده‌ها تو را در صفحه پایین می‌برند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x06-l1-ctx","exam":true,"patterns":["L1-forms","PARA-time"],"often":{"pattern":"L1-forms","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Getting help from the council","tr":"Belediyeden yardım almak","fa":"گرفتن کمک از شهرداری"},"asks":{"en":"One person asks a neighbour how to get official help for an elderly parent. The notes follow the steps: how to apply, what help there is, who to contact, and support for the carer.","tr":"Biri, yaşlı bir anne ya da baba için resmî yardımı nasıl alacağını bir komşusuna soruyor. Notlar adımları izliyor: nasıl başvurulur, ne tür yardım var, kiminle iletişime geçilir ve bakım verene destek.","fa":"یک نفر از همسایه‌اش می‌پرسد چطور برای پدر یا مادرِ سالمندش کمک رسمی بگیرد. یادداشت‌ها قدم‌ها را دنبال می‌کنند: چطور درخواست بدهی، چه کمک‌هایی هست، با چه کسی تماس بگیری و حمایت از کسی که مراقبت می‌کند."},"fields":["Applying","Waiting time","What to prepare","Help at home","Contact","Day centre","Activities","Support for carers","Grants"],"words":[{"a":"assessment","b":"someone comes to see what she can and can’t do","tr":"değerlendirme","fa":"ارزیابی"},{"a":"apply","b":"ask for it officially / fill in the form","tr":"başvurmak","fa":"درخواست دادن"},{"a":"within 14 days","b":"in the next two weeks / no later than","tr":"14 gün içinde","fa":"ظرف ۱۴ روز"},{"a":"medication","b":"her medicines / tablets","tr":"ilaçlar","fa":"داروها"},{"a":"carer","b":"someone who looks after another person","tr":"bakım veren kişi","fa":"مراقب"},{"a":"day centre","b":"a place people go for lunch and activities","tr":"gündüz bakım merkezi","fa":"مرکز روزانه"},{"a":"respite / a break","b":"a few hours off / time to go out","tr":"mola, dinlenme","fa":"استراحت، فرصت نفس کشیدن"},{"a":"grant","b":"money you don’t pay back","tr":"hibe, ödenek","fa":"کمک‌هزینه‌ی بلاعوض"},{"a":"cut back","b":"made shorter / reduced","tr":"kısıtladılar","fa":"کمش کردند"},{"a":"every other week","b":"once a fortnight","tr":"iki haftada bir","fa":"یک هفته در میان"}],"traps":[{"en":"Numbers that sound alike: fourteen and forty, fifteen and fifty. Speakers sometimes say the digits (\"one-four\"). Listen to the end of the word.","tr":"Birbirine benzeyen sayılar: fourteen ve forty, fifteen ve fifty. Konuşanlar bazen rakamları tek tek söyler (\"one-four\"). Kelimenin sonunu dinle.","fa":"عددهایی که شبیه هم‌اند: fourteen و forty، fifteen و fifty. گاهی گوینده رقم‌ها را جدا می‌گوید («one-four»). به آخر کلمه گوش بده."},{"en":"A detail that has changed: \"It was open on Saturdays, but they’ve stopped that.\" Write what is true now.","tr":"Değişmiş bir bilgi: \"Cumartesi açıktı ama bunu bıraktılar.\" Şimdi doğru olanı yaz.","fa":"اطلاعاتی که عوض شده: «شنبه‌ها باز بود، ولی دیگر نه». چیزی را بنویس که الان درست است."},{"en":"Help from somewhere else: the question asks about the council, but the speaker says one thing came from a charity. Check who gives what.","tr":"Başka bir yerden gelen yardım: soru belediyeyi soruyor ama konuşan bir şeyin bir yardım kuruluşundan geldiğini söylüyor. Neyi kimin verdiğine bak.","fa":"کمک از جای دیگر: سؤال درباره‌ی شهرداری است، اما گوینده می‌گوید یک چیز را یک خیریه داد. ببین چه کسی چه چیزی می‌دهد."}],"example":{"lines":[["Neighbour 1","When does the lunch club meet?"],["Neighbour 2","It used to be Thursdays, but the hall’s booked then now, so it’s moved to Mondays."]],"item":"Lunch club: every ___","answer":"Monday","why":{"en":"Thursday was the old day. \"It’s moved to Mondays\" is true now.","tr":"Perşembe eski gündü. \"Pazartesiye taşındı\" şimdi doğru olan.","fa":"پنجشنبه روزِ قبلی بود. «به دوشنبه‌ها منتقل شده» الان درست است."}}},{"id":"L1-forms","ctx":["L1-forms"],"title":{"en":"A survey or an official form","tr":"Bir anket ya da resmî bir form","fa":"نظرسنجی یا فرم رسمی"},"asks":{"en":"An interviewer asks a member of the public questions (a shopping, transport or customer survey), or an official takes details for a report or a registration. The form collects personal details, reasons, opinions and suggestions.","tr":"Bir anketör halktan birine sorular sorar (alışveriş, ulaşım ya da müşteri anketi) ya da bir görevli bir tutanak veya kayıt için bilgi alır. Form kişisel bilgileri, nedenleri, görüşleri ve önerileri toplar.","fa":"یک پرسشگر از یک نفر سؤال می‌پرسد (نظرسنجی خرید، حمل‌ونقل یا رضایت مشتری)، یا یک مأمور برای گزارش یا ثبت‌نام اطلاعات می‌گیرد. فرم مشخصات شخصی، دلیل‌ها، نظرها و پیشنهادها را جمع می‌کند."},"fields":["Name / age group","Occupation","Postcode","Reason for journey or visit","How often","What was good","What could be improved","Date and time of incident"],"words":[{"a":"occupation","b":"what do you do / I'm a","tr":"meslek","fa":"شغل"},{"a":"reason for visit","b":"why did you come / I'm here to","tr":"ziyaret nedeni","fa":"دلیل مراجعه"},{"a":"how often","b":"about twice a month","tr":"ne sıklıkta","fa":"هر چند وقت یک بار"},{"a":"satisfied","b":"happy with / pleased with","tr":"memnun","fa":"راضی"},{"a":"complaint","b":"what annoyed me was","tr":"şikâyet","fa":"شکایت"},{"a":"suggestion","b":"it would be better if","tr":"öneri","fa":"پیشنهاد"},{"a":"date of birth","b":"when were you born","tr":"doğum tarihi","fa":"تاریخ تولد"},{"a":"incident","b":"what happened","tr":"olay","fa":"حادثه"},{"a":"stolen","b":"someone took","tr":"çalınmış","fa":"دزدیده‌شده"},{"a":"registered","b":"your name is on our list","tr":"kayıtlı","fa":"ثبت‌شده"},{"a":"improve","b":"should be changed / make it better","tr":"iyileştirmek","fa":"بهتر کردن"},{"a":"means of transport","b":"I came by / I usually drive","tr":"ulaşım şekli","fa":"وسیله‌ی رفت‌وآمد"}],"traps":[{"en":"Opinion questions: the person first says what was fine, then what was wrong. The form usually asks for the problem.","tr":"Görüş soruları: kişi önce neyin iyi olduğunu, sonra neyin kötü olduğunu söyler. Form genellikle sorunu sorar.","fa":"سؤال‌های نظری: آدم اول می‌گوید چه چیزی خوب بود، بعد چه چیزی بد بود. فرم معمولاً مشکل را می‌پرسد."},{"en":"Personal details (age group, occupation, postcode) are said quickly and in passing.","tr":"Kişisel bilgiler (yaş grubu, meslek, posta kodu) hızlı ve laf arasında söylenir.","fa":"مشخصات شخصی (گروه سنی، شغل، کد پستی) سریع و در میان حرف گفته می‌شوند."},{"en":"Descriptions of a lost or stolen item: colour, size and material, then one detail is corrected.","tr":"Kayıp ya da çalınan bir eşyanın tarifi: renk, boyut ve malzeme; sonra bir ayrıntı düzeltilir.","fa":"توصیف یک وسیله‌ی گم‌شده یا دزدیده‌شده: رنگ، اندازه و جنس؛ بعد یکی از جزئیات اصلاح می‌شود."}],"example":{"lines":[["Interviewer","How was the journey overall?"],["Passenger","The seats were comfortable, and the staff were friendly."],["Passenger","The only thing was the wifi. It kept cutting out."]],"item":"Problem with the journey: the ___","answer":"wifi","why":{"en":"Seats and staff were positive. \"The only thing was\" introduces the problem: the wifi.","tr":"Koltuklar ve personel olumlu. \"The only thing was\" sorunu getiriyor: wifi.","fa":"صندلی‌ها و کارکنان مثبت بودند. «The only thing was» مشکل را معرفی می‌کند: wifi."}},"general":true,"patterns":["L1-forms"],"often":{"pattern":"L1-forms","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Ten notes, one break","tr":"On not, bir ara","fa":"ده یادداشت، یک وقفه"},"body":{"en":"All ten questions are notes. You read Questions 1-5 first, then Questions 6-10 in the break. The answers come in order. Limit: ONE WORD AND/OR A NUMBER, so a number can be written in figures.","tr":"On sorunun hepsi nottur. Önce Soru 1-5’i, aradaki molada Soru 6-10’u okursun. Cevaplar sırayla gelir. Sınır: ONE WORD AND/OR A NUMBER, yani bir sayı rakamla yazılabilir.","fa":"هر ده سؤال یادداشت‌اند. اول سؤال‌های ۱ تا ۵ را می‌خوانی و در وقفه سؤال‌های ۶ تا ۱۰ را. جواب‌ها به ترتیب می‌آیند. سقف: ONE WORD AND/OR A NUMBER، پس عدد را می‌شود با رقم نوشت."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read each line and predict: a number, a day, a name, an action or a thing.","tr":"Her satırı oku ve tahmin et: sayı, gün, isim, eylem ya da eşya.","fa":"هر خط را بخوان و حدس بزن: عدد، روز، اسم، کار یا چیز."},{"en":"For numbers, listen to the end of the word: -teen is stressed and long, -ty is short.","tr":"Sayılarda kelimenin sonunu dinle: -teen vurgulu ve uzun, -ty kısa.","fa":"در عددها به آخر کلمه گوش بده: ‎-teen تکیه‌دار و کشیده است و ‎-ty کوتاه."},{"en":"For a spelled name, write each letter as you hear it; \"two Ds\" means DD.","tr":"Harf harf söylenen bir isimde her harfi duyduğun gibi yaz; \"two Ds\" DD demektir.","fa":"در اسمی که هجی می‌شود، هر حرف را همان‌طور که می‌شنوی بنویس؛ «two Ds» یعنی DD."},{"en":"When a speaker says \"used to\" or \"they’ve changed it\", wait for the new detail.","tr":"Konuşan \"used to\" ya da \"they’ve changed it\" deyince yeni bilgiyi bekle.","fa":"وقتی گوینده «used to» یا «they’ve changed it» می‌گوید، منتظر اطلاعات جدید بمان."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Who gives what","tr":"Neyi kim veriyor","fa":"چه کسی چه چیزی می‌دهد"},"body":{"en":"In a conversation about a service, the speaker may mention several kinds of help and several providers. Check that your answer is the help the note asks about, from the provider in the note, and not something that was ruled out or came from elsewhere.","tr":"Bir hizmet hakkındaki konuşmada konuşan birkaç tür yardımdan ve birkaç kurumdan söz edebilir. Cevabının, notun sorduğu yardım olduğundan, notta geçen kurumdan geldiğinden emin ol; elenen ya da başka yerden gelen bir şey olmasın.","fa":"در گفتگویی درباره‌ی یک خدمت، ممکن است گوینده از چند نوع کمک و چند جای مختلف حرف بزند. مطمئن شو جوابت همان کمکی است که یادداشت می‌پرسد، از همان جایی که در یادداشت آمده، و چیزی نیست که رد شده یا از جای دیگری آمده."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One gap, step by step","tr":"Bir boşluk, adım adım","fa":"یک جای خالی، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","item":"Library home service · books delivered every ___ days","lines":[["Neighbour 1","How often do they bring the books?"],["Neighbour 2","Every fifteen days. Fifteen, one-five. It used to be once a month, but people asked for more."]],"answer":"15","walk":[{"en":"Before you listen: the gap needs a number of days.","tr":"Dinlemeden önce: boşluk gün sayısı istiyor.","fa":"قبل از گوش دادن: جای خالی تعداد روز می‌خواهد."},{"en":"\"Fifteen, one-five\" confirms it is 15, not 50.","tr":"\"Fifteen, one-five\" 50 değil 15 olduğunu doğruluyor.","fa":"«fifteen, one-five» تأیید می‌کند ۱۵ است، نه ۵۰."},{"en":"\"Once a month\" was the old service. Write 15.","tr":"\"Ayda bir\" eski hizmetti. 15 yaz.","fa":"«ماهی یک بار» خدمت قبلی بود. 15 را بنویس."}]},"quick":{"prompt":"Notes: \"Meeting room holds ___ people\". You hear: \"It takes thirty. Three-oh. Not thirteen, I always get that wrong.\" What do you write?","options":["13","30","3"],"correct":1,"why":{"en":"\"Three-oh\" gives the digits: 30.","tr":"\"Three-oh\" rakamları veriyor: 30.","fa":"«three-oh» رقم‌ها را می‌گوید: ۳۰."}},"remember":{"en":"Predict the kind of answer, listen to the end of every number, and write the detail that is true now.","tr":"Cevabın türünü tahmin et, her sayının sonunu dinle ve şu anda doğru olan bilgiyi yaz.","fa":"نوع جواب را حدس بزن، به آخر هر عدد گوش بده و اطلاعاتی را بنویس که الان درست است."},"type":"explain","id":"c-x06-l1-e","course":"ielts-exams","exam":"exam-06","unit":"x06-l1"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 1","title":{"en":"Help for a parent who needs care","tr":"Bakıma ihtiyacı olan bir ebeveyn için yardım","fa":"کمک برای والدی که به مراقبت نیاز دارد"},"timed":8,"ctx":["L1-forms"],"script":[{"who":"Bridget","line":"Martin, have you got a minute? I wanted to ask you about the help you got for your dad."},{"who":"Martin","line":"Of course. Is it your mum?"},{"who":"Bridget","line":"Yes. She's managing at home, just about, but she's finding things harder, and I'm going round three times a day. Someone said the council can help, but I don't know where to start."},{"who":"Martin","line":"The first thing is to ask for an assessment. It's free, and it doesn't matter how much money your mum has. Someone from the council comes to the house and looks at what she can and can't do."},{"who":"Bridget","line":"How long do you have to wait for that?"},{"who":"Martin","line":"They say they'll visit within fourteen days. That's one-four, not four-oh, though when we applied it was actually a bit quicker."},{"who":"Bridget","line":"That's not bad. Do I need to prepare anything?"},{"who":"Martin","line":"They'll ask a lot of questions about her health, so have a list of all her medication ready. That saves a lot of time. They don't need her bank details at that stage."},{"who":"Bridget","line":"OK. And what kind of help could she get?"},{"who":"Martin","line":"For Dad, the most useful thing was a carer who came every morning. She helped him get dressed and made sure he'd had breakfast. He could still wash on his own, so they didn't do that."},{"who":"Bridget","line":"Mum would hate a stranger helping her wash anyway. Who should I talk to at the council?"},{"who":"Martin","line":"We dealt with a woman called Joanna Ruddock. She was brilliant."},{"who":"Bridget","line":"How do you spell her surname?"},{"who":"Martin","line":"R-U-D-D-O-C-K. Two Ds."},{"who":"Bridget","line":"Thanks. Now, what about during the day? Mum gets quite lonely."},{"who":"Martin","line":"There's a day centre on Mill Road. People go for lunch, there's music, sometimes a quiz. When Dad started, it was open Monday to Friday, but they've cut it back since then. It's Monday to Thursday now."},{"who":"Bridget","line":"Is there transport? Mum doesn't drive any more."},{"who":"Martin","line":"Yes, a minibus picks people up at about ten. And there's something else your mum might like, if her memory's getting worse. On Wednesday afternoons the library runs a memory café. It's very relaxed: tea, old photos, a bit of singing."},{"who":"Bridget","line":"She'd probably enjoy that more than the day centre, to be honest."},{"who":"Martin","line":"And don't forget about yourself. The council has a sitting service for carers. Someone stays with your mum for three hours a week so that you can go out. I used it to go swimming."},{"who":"Bridget","line":"That sounds wonderful. What about the house? The bathroom's a real problem. She can't get into the bath."},{"who":"Martin","line":"You can apply for a grant for that. They paid for Dad to have a walk-in shower. A stair rail was the other thing we wanted, but that came from a charity, not the council."},{"who":"Bridget","line":"Right. And is there anywhere I can talk to other people in the same situation?"},{"who":"Martin","line":"There's a carers' group at the community hall. They used to meet on the last Friday of the month, but most people work on Fridays, so now it's the first Tuesday of every month, in the evening."},{"who":"Bridget","line":"The first Tuesday. I'll try to go next month."},{"who":"Martin","line":"Do. It really helped me to know I wasn't the only one."},{"who":"Bridget","line":"Thanks so much, Martin. I'll ring the council this afternoon."}],"notes":{"title":"Council support: notes for Bridget’s mother","lines":["Applying","First ask for a free (1) ___ of her needs","A visit within (2) ___ days","Have a list of all her (3) ___ ready","Help at home: a carer helps her get (4) ___ in the morning","Council contact: Joanna (5) ___","Other support","Day centre: open Monday to (6) ___","Wednesday afternoons: a memory (7) ___ at the library","Support for carers: a (8) ___ service gives three hours off a week","Grants: help to pay for a walk-in (9) ___","Carers’ group: meets on the first (10) ___ of each month"]},"groups":[{"instruction":"Questions 1-10. Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","qtype":"note","questions":[{"n":1,"kind":"gap","prompt":"Applying · first ask for a free ___ of her needs","accept":["assessment"],"limit":1,"evidence":"The first thing is to ask for an assessment","why":{"en":"\"The first thing is to ask for an assessment. It’s free.\"","tr":"\"İlk iş bir değerlendirme istemek. Ücretsiz.\"","fa":"«اولین کار درخواست ارزیابی است. رایگان است»."},"trap":["TR-paraphrase"]},{"n":2,"kind":"gap","prompt":"Applying · a visit within ___ days","accept":["14","fourteen"],"limit":1,"evidence":"They say they'll visit within fourteen days","why":{"en":"\"Fourteen days. That’s one-four, not four-oh.\"","tr":"\"On dört gün. Yani bir-dört, dört-sıfır değil.\"","fa":"«چهارده روز. یعنی یک-چهار، نه چهار-صفر»."},"trap":["TR-number"]},{"n":3,"kind":"gap","prompt":"Applying · have a list of all her ___ ready","accept":["medication"],"limit":1,"evidence":"have a list of all her medication ready","why":{"en":"\"Have a list of all her medication ready.\" Bank details are not needed yet.","tr":"\"Tüm ilaçlarının bir listesini hazır tut.\" Banka bilgileri henüz gerekmiyor.","fa":"«فهرست همه‌ی داروهایش را آماده داشته باش». مشخصات بانکی هنوز لازم نیست."},"trap":["TR-paraphrase"]},{"n":4,"kind":"gap","prompt":"Help at home · a carer helps her get ___ in the morning","accept":["dressed"],"limit":1,"evidence":"She helped him get dressed","why":{"en":"\"She helped him get dressed.\" Washing was not part of the help.","tr":"\"Giyinmesine yardım ediyordu.\" Yıkanmak yardımın bir parçası değildi.","fa":"«کمکش می‌کرد لباس بپوشد». شستشو جزو کمک نبود."},"trap":["TR-paraphrase"]},{"n":5,"kind":"gap","prompt":"Council contact · Joanna ___","accept":["Ruddock"],"limit":1,"evidence":"R-U-D-D-O-C-K","why":{"en":"Spelled R-U-D-D-O-C-K: \"two Ds\".","tr":"R-U-D-D-O-C-K diye harf harf: \"iki D\".","fa":"حرف به حرف: R-U-D-D-O-C-K، «دو تا D»."},"trap":["TR-spell"]},{"n":6,"kind":"gap","prompt":"Day centre · open Monday to ___","accept":["Thursday"],"limit":1,"evidence":"It's Monday to Thursday now","why":{"en":"Friday was when Martin’s dad started. \"It’s Monday to Thursday now.\"","tr":"Cuma, Martin’in babasının başladığı zamandı. \"Artık pazartesiden perşembeye.\"","fa":"جمعه مال وقتی بود که پدر مارتین شروع کرد. «الان دوشنبه تا پنجشنبه است»."},"trap":["TR-selfcorrect"]},{"n":7,"kind":"gap","prompt":"Wednesday afternoons · a memory ___ at the library","accept":["café","cafe"],"limit":1,"evidence":"the library runs a memory café","why":{"en":"\"On Wednesday afternoons the library runs a memory café.\"","tr":"\"Çarşamba öğleden sonraları kütüphane bir hafıza kafesi düzenliyor.\"","fa":"«بعدازظهرهای چهارشنبه کتابخانه یک کافه‌ی حافظه برگزار می‌کند»."},"trap":["TR-paraphrase"]},{"n":8,"kind":"gap","prompt":"Support for carers · a ___ service gives three hours off a week","accept":["sitting"],"limit":1,"evidence":"The council has a sitting service for carers","why":{"en":"\"A sitting service for carers\": someone stays with the parent so the carer can go out.","tr":"\"Bakım verenler için bir refakat hizmeti\": biri ebeveynle kalıyor, bakım veren dışarı çıkabiliyor.","fa":"«خدمت همراهی برای مراقب‌ها»: کسی پیش پدر یا مادر می‌ماند تا مراقب بتواند بیرون برود."},"trap":["TR-paraphrase"]},{"n":9,"kind":"gap","prompt":"Grants · help to pay for a walk-in ___","accept":["shower"],"limit":1,"evidence":"They paid for Dad to have a walk-in shower","why":{"en":"The council paid for \"a walk-in shower\". The stair rail came from a charity.","tr":"Belediye \"basamaksız bir duşun\" parasını ödedi. Merdiven tutamağı bir yardım kuruluşundan geldi.","fa":"شهرداری پول «دوشِ بدون پله» را داد. نرده‌ی پله را یک خیریه داد."},"trap":["TR-paraphrase"]},{"n":10,"kind":"gap","prompt":"Carers’ group · meets on the first ___ of each month","accept":["Tuesday"],"limit":1,"evidence":"now it's the first Tuesday of every month","why":{"en":"The last Friday was the old day. \"Now it’s the first Tuesday of every month.\"","tr":"Ayın son cuması eski gündü. \"Artık her ayın ilk salısı.\"","fa":"آخرین جمعه‌ی ماه روز قبلی بود. «الان اولین سه‌شنبه‌ی هر ماه است»."},"trap":["TR-selfcorrect"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Bridget":{"accent":"Irish","gender":"F","tts":{"engine":"kokoro","voice":"bf_emma","fallback":true,"note":"Irish wanted; no free Irish voice yet"},"role":"Neighbour asking for advice"},"Martin":{"accent":"British (Southern English)","gender":"M","tts":{"engine":"kokoro","voice":"bm_daniel"},"role":"Neighbour who has used the service"}},"sequence":[{"type":"announcer","text":"Part 1. You will hear two neighbours talking about support that the local council offers to people who care for an elderly parent. First, you have some time to look at Questions 1 to 5."},{"type":"pause","seconds":30,"note":"reading time, Questions 1-5"},{"type":"announcer","text":"Now listen carefully and answer Questions 1 to 5."},{"type":"sfx","note":"quiet front garden or street, a door closing at the start"},{"type":"lines","from":0,"to":13},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 6 to 10."},{"type":"pause","seconds":30,"note":"reading time, Questions 6-10"},{"type":"announcer","text":"Now listen and answer Questions 6 to 10."},{"type":"lines","from":14,"to":26},{"type":"announcer","text":"That is the end of Part 1. You now have half a minute to check your answers.","after":30}]},"id":"c-x06-l1-d","course":"ielts-exams","exam":"exam-06","unit":"x06-l1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The council will do an assessment first.\" An assessment is...","options":["a visit to find out what someone needs","a bill for the service","a form to cancel help"],"correct":0,"why":{"en":"An assessment checks what a person can and cannot do, so the right help can be given.","tr":"Değerlendirme, doğru yardımın verilmesi için bir kişinin neyi yapıp neyi yapamadığına bakar.","fa":"ارزیابی بررسی می‌کند فرد چه کارهایی را می‌تواند و نمی‌تواند انجام بدهد تا کمک درست داده شود."}},{"tests":"paraphrase","point":1,"prompt":"Notes say \"a few hours off for the carer\". Which words in a recording mean the same?","options":["you can phone us at any time","we come round in the evenings","someone stays with her so you can go out"],"correct":2,"why":{"en":"If someone stays with the parent, the carer gets time off.","tr":"Biri ebeveynle kalırsa bakım veren boş zaman bulur.","fa":"اگر کسی پیش پدر یا مادر بماند، مراقب وقت آزاد پیدا می‌کند."}},{"tests":"method","point":2,"prompt":"You hear: \"The group has fifty members. Five-oh.\" The note says \"___ members\". What do you write?","options":["15","50","5"],"correct":1,"why":{"en":"\"Five-oh\" gives the digits 5 and 0: fifty.","tr":"\"Five-oh\" 5 ve 0 rakamlarını veriyor: elli.","fa":"«five-oh» رقم‌های ۵ و ۰ را می‌دهد: پنجاه."}},{"tests":"method","point":2,"prompt":"A name is spelled: \"G-A-double-R-E-T-T\". What do you write?","options":["Garrett","Garett","Garret"],"correct":0,"why":{"en":"Double R and double T: G-A-R-R-E-T-T.","tr":"Çift R ve çift T: G-A-R-R-E-T-T.","fa":"دو R و دو T: G-A-R-R-E-T-T."}},{"tests":"trap","point":3,"prompt":"Note: \"Council grant paid for a new ___\". You hear: \"The council paid for the ramp. The handrail came from a charity.\" What do you write?","options":["handrail","charity","ramp"],"correct":2,"why":{"en":"The note asks what the council paid for: the ramp. The handrail came from somewhere else.","tr":"Not belediyenin neyi ödediğini soruyor: rampa. Tutamak başka yerden geldi.","fa":"یادداشت می‌پرسد شهرداری پول چه چیزی را داد: رمپ. نرده از جای دیگری آمد."}}],"id":"c-x06-l1-x","course":"ielts-exams","exam":"exam-06","unit":"x06-l1"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
